/// Success exit code.
pub const FC_EXIT_CODE_OK: u8 = 0;
/// Generic error exit code.
pub const FC_EXIT_CODE_GENERIC_ERROR: u8 = 1;
/// Generic exit code for an error considered not possible to occur if the program logic is sound.
#[cfg(target_os = "linux")]
pub const FC_EXIT_CODE_UNEXPECTED_ERROR: u8 = 2;
/// Process exit code meaning the guest asked to reset (reboot), as opposed to a clean
/// power-off (`FC_EXIT_CODE_OK`): a triple fault, `KVM_SYSTEM_EVENT_RESET`, the i8042
/// CPU-reset command or the ACPI reset register. A supervisor can relaunch the VM on it to
/// reboot in place (local patch, see VENDOR.md).
pub const KRUN_EXIT_GUEST_RESET: u8 = 154;
/// Errors associated with the VMM internal logic. These errors cannot be generated by direct user
/// input, but can result from bad configuration of the host (for example if Firecracker doesn't
/// have permissions to open the KVM fd).
#[derive(Debug)]
#[allow(unused)]
pub enum Error {
    /// This error is thrown by the minimal boot loader implementation.
    ConfigureSystem(arch::Error),
    /// Legacy devices work with Event file descriptors and the creation can fail because
    /// of resource exhaustion.
    #[cfg(target_arch = "x86_64")]
    CreateLegacyDevice(device_manager::legacy::Error),
    /// Cannot read from an Event file descriptor.
    EventFd(io::Error),
    /// Cannot open /dev/kvm. Either the host does not have KVM or Firecracker does not have
    /// permission to open the file descriptor.
    KvmContext(vstate::Error),
    #[cfg(target_arch = "x86_64")]
    /// Cannot add devices to the Legacy I/O Bus.
    LegacyIOBus(device_manager::legacy::Error),
    /// Cannot add a device to the MMIO Bus.
    RegisterMMIODevice(device_manager::mmio::Error),
    #[cfg(any(target_arch = "aarch64", target_arch = "riscv64"))]
    /// Cannot generate or write FDT
    SetupFDT(devices::fdt::Error),
    /// Vcpu error.
    Vcpu(vstate::Error),
    /// Cannot send event to vCPU.
    VcpuEvent(vstate::Error),
    /// Cannot create a vCPU handle.
    VcpuHandle(vstate::Error),
    /// vCPU resume failed.
    VcpuResume,
    /// Vm error.
    Vm(vstate::Error),
}

impl Display for Error {
    fn fmt(&self, f: &mut Formatter) -> std::fmt::Result {
        use self::Error::*;

        match self {
            ConfigureSystem(e) => write!(f, "System configuration error: {e:?}"),
            #[cfg(target_arch = "x86_64")]
            CreateLegacyDevice(e) => write!(f, "Error creating legacy device: {e:?}"),
            EventFd(e) => write!(f, "Event fd error: {e}"),
            KvmContext(e) => write!(f, "Failed to validate KVM support: {e:?}"),
            #[cfg(target_arch = "x86_64")]
            LegacyIOBus(e) => write!(f, "Cannot add devices to the legacy I/O Bus. {e}"),
            RegisterMMIODevice(e) => write!(f, "Cannot add a device to the MMIO Bus. {e}"),
            #[cfg(any(target_arch = "aarch64", target_arch = "riscv64"))]
            SetupFDT(e) => write!(f, "Error generating or writing FDT: {e:?}"),
            Vcpu(e) => write!(f, "Vcpu error: {e}"),
            VcpuEvent(e) => write!(f, "Cannot send event to vCPU. {e:?}"),
            VcpuHandle(e) => write!(f, "Cannot create a vCPU handle. {e}"),
            VcpuResume => write!(f, "vCPUs resume failed."),
            Vm(e) => write!(f, "Vm error: {e}"),
        }
    }
}

/// Shorthand result type for internal VMM commands.
pub type Result<T> = std::result::Result<T, Error>;

/// Contains the state and associated methods required for the Firecracker VMM.
pub struct Vmm {
    // Guest VM core resources.
    pub(crate) guest_memory: GuestMemoryMmap,
    pub(crate) arch_memory_info: ArchMemoryInfo,

    pub(crate) kernel_cmdline: KernelCmdline,

    pub(crate) vcpus_handles: Vec<VcpuHandle>,
    pub(crate) exit_evt: EventFd,
    #[cfg(not(target_os = "windows"))]
    pub(crate) vm: Vm,
    pub(crate) exit_observers: Vec<Arc<Mutex<dyn VmmExitObserver>>>,
    pub(crate) exit_code: Arc<AtomicI32>,
    /// Set by a device (i8042 CPU-reset, ACPI reset register) before it fires `exit_evt`, to
    /// mark the exit as a guest reset. See `KRUN_EXIT_GUEST_RESET`.
    pub(crate) reset_flag: Arc<AtomicBool>,
    /// The code of a vCPU that answered a pause or resume with `Exited`, for the `exit_evt`
    /// handler, which otherwise reads it off the vCPU's response channel.
    pub(crate) vcpu_exit_code: Option<u8>,

    // Guest VM devices.
    pub(crate) mmio_device_manager: MMIODeviceManager,
    #[cfg(all(target_arch = "x86_64", target_os = "linux"))]
    pub(crate) pci_device_manager: Option<PciHostManager>,

    // Out-of-band live pause/resume requests: the C API sends `VmCtl` from
    // another thread; the event loop freezes or wakes the vCPUs. A single
    // channel rather than one eventfd per operation, so the event loop observes
    // the requests in the order they were made. Device worker threads are
    // notify-driven, so a frozen guest leaves them idle without explicit
    // handling.
    #[cfg(any(target_os = "macos", target_os = "linux"))]
    pub(crate) vm_ctl_tx: PollableChannelSender<VmCtl>,
    #[cfg(any(target_os = "macos", target_os = "linux"))]
    pub(crate) vm_ctl_rx: PollableChannelReciever<VmCtl>,
    #[cfg(any(target_os = "macos", target_os = "linux"))]
    pub(crate) paused: bool,
    /// The legacy devices a snapshot keeps (local patch).
    #[cfg(all(target_os = "linux", target_arch = "x86_64", feature = "snapshot"))]
    pub(crate) legacy_devices: Option<snapshot::LegacyDevices>,
    /// The VM generation ID the DSDT declares, which a restore puts back in place of the
    /// snapshot's (local patch).
    #[cfg(all(target_os = "linux", target_arch = "x86_64", feature = "snapshot"))]
    pub(crate) vm_generation_id: Option<[u8; 16]>,
    #[cfg(target_os = "macos")]
    pub(crate) paused_at: u64,
}

/// A paused VM's CPU state: its vCPUs' and its in-kernel devices'.
#[cfg(all(target_os = "linux", target_arch = "x86_64"))]
#[derive(Debug)]
#[cfg_attr(feature = "snapshot", derive(serde::Serialize, serde::Deserialize))]
#[cfg_attr(test, derive(Default))]
pub struct CpuState {
    pub vm: vstate::VmState,
    pub vcpus: Vec<vstate::VcpuState>,
}

/// Out-of-band request to the running VM's event loop.
#[cfg(any(target_os = "macos", target_os = "linux"))]
#[derive(Debug, Clone)]
pub enum VmCtl {
    /// Pause the VM; the outcome comes back on the sender.
    Pause(Sender<std::result::Result<(), String>>),
    /// Resume the VM; the outcome comes back on the sender.
    Resume(Sender<std::result::Result<(), String>>),
    /// Pause the VM and write its snapshot to this directory; the VM stays paused. The result
    /// comes back on the sender.
    #[cfg(all(target_os = "linux", target_arch = "x86_64", feature = "snapshot"))]
    Snapshot(std::path::PathBuf, Sender<std::result::Result<(), String>>),
    /// End the VM as a guest power-off does (devices flush on the way out).
    #[cfg(all(target_os = "linux", target_arch = "x86_64", feature = "snapshot"))]
    Quit,
}

impl Vmm {
    /// Starts the microVM vcpus.
    pub fn start_vcpus(&mut self, mut vcpus: Vec<Vcpu>) -> Result<()> {
        let vcpu_count = vcpus.len();

        Vcpu::register_kick_signal_handler();

        self.vcpus_handles.reserve(vcpu_count);

        for mut vcpu in vcpus.drain(..) {
            vcpu.set_mmio_bus(self.mmio_device_manager.bus.clone());

            self.vcpus_handles
                .push(vcpu.start_threaded().map_err(Error::VcpuHandle)?);
        }

        // The vcpus start off in the `Paused` state, let them run.
        self.resume_vcpus()?;

        Ok(())
    }

    /// Start the vCPU threads but leave them paused, for a restore to set them up first.
    #[cfg(all(target_os = "linux", target_arch = "x86_64", feature = "snapshot"))]
    pub fn start_vcpus_paused(&mut self, mut vcpus: Vec<Vcpu>) -> Result<()> {
        Vcpu::register_kick_signal_handler();
        self.vcpus_handles.reserve(vcpus.len());
        for mut vcpu in vcpus.drain(..) {
            vcpu.set_mmio_bus(self.mmio_device_manager.bus.clone());
            self.vcpus_handles
                .push(vcpu.start_threaded().map_err(Error::VcpuHandle)?);
        }
        self.paused = true;
        Ok(())
    }

    /// Sends a resume command to the vcpus.
    #[cfg(target_os = "linux")]
    pub fn resume_vcpus(&mut self) -> Result<()> {
        for handle in self.vcpus_handles.iter() {
            handle
                .send_event(VcpuEvent::Resume)
                .map_err(Error::VcpuEvent)?;
        }
        for handle in self.vcpus_handles.iter() {
            match handle
                .response_receiver()
                .recv_timeout(Duration::from_millis(1000))
            {
                Ok(VcpuResponse::Resumed) => (),
                _ => return Err(Error::VcpuResume),
            }
        }
        Ok(())
    }

    #[cfg(target_os = "macos")]
    pub fn resume_vcpus(&mut self) -> Result<()> {
        Ok(())
    }

    #[cfg(target_os = "windows")]
    pub fn resume_vcpus(&mut self) -> Result<()> {
        for handle in self.vcpus_handles.iter() {
            handle
                .send_event(VcpuEvent::Resume)
                .map_err(Error::VcpuEvent)?;
        }
        for handle in self.vcpus_handles.iter() {
            match handle
                .response_receiver()
                .recv_timeout(Duration::from_millis(1000))
            {
                Ok(VcpuResponse::Resumed) => (),
                _ => return Err(Error::VcpuResume),
            }
        }
        Ok(())
    }

    /// Sender for live [`VmCtl`] requests. The event loop runs [`Vmm::pause`] /
    /// [`Vmm::resume`] in response.
    #[cfg(any(target_os = "macos", target_os = "linux"))]
    pub fn vm_ctl_sender(&self) -> PollableChannelSender<VmCtl> {
        self.vm_ctl_tx.clone()
    }

    /// Freeze every vCPU at an instruction boundary. Reversible via [`Vmm::resume`];
    /// the guest's virtual counter is held so timers don't fire en masse on wake.
    /// Idempotent: pausing an already-paused VM is a no-op.
    #[cfg(target_os = "macos")]
    pub fn pause(&mut self) -> std::result::Result<(), String> {
        use crate::vmm::vstate::{VcpuEvent, VcpuResponse};
        if self.paused {
            return Ok(());
        }
        for h in &self.vcpus_handles {
            h.send_event(VcpuEvent::Pause)
                .map_err(|e| format!("vcpu pause event: {e:?}"))?;
            hvf::vcpu_request_exit(h.hvf_id()).map_err(|e| format!("vcpu_request_exit: {e:?}"))?;
        }
        for h in &self.vcpus_handles {
            match h.response_receiver().recv() {
                Ok(VcpuResponse::Paused) => {}
                Ok(other) => return Err(format!("unexpected vcpu response: {other:?}")),
                Err(e) => return Err(format!("vcpu response: {e:?}")),
            }
        }
        self.paused_at = unsafe { hvf::mach_absolute_time() };
        self.paused = true;
        Ok(())
    }

    /// Wake every vCPU previously frozen by [`Vmm::pause`], advancing the vtimer
    /// offset by the time spent paused. Idempotent: resuming a running VM is a
    /// no-op.
    #[cfg(target_os = "macos")]
    pub fn resume(&mut self) -> std::result::Result<(), String> {
        use crate::vmm::vstate::{VcpuEvent, VcpuResponse};
        if !self.paused {
            return Ok(());
        }
        let paused_ticks = unsafe { hvf::mach_absolute_time() }.saturating_sub(self.paused_at);
        for h in &self.vcpus_handles {
            h.send_event(VcpuEvent::Resume(paused_ticks))
                .map_err(|e| format!("vcpu resume event: {e:?}"))?;
        }
        for h in &self.vcpus_handles {
            match h.response_receiver().recv() {
                Ok(VcpuResponse::Resumed) => {}
                Ok(other) => return Err(format!("unexpected vcpu response: {other:?}")),
                Err(e) => return Err(format!("vcpu response: {e:?}")),
            }
        }
        self.paused = false;
        Ok(())
    }

    /// Freeze every vCPU: each leaves `KVM_RUN` (its kick signal sets `immediate_exit`, which
    /// completes a pending I/O first) and parks. Reversible via [`Vmm::resume`]. Idempotent:
    /// pausing an already-paused VM is a no-op. On failure the VM runs on.
    #[cfg(target_os = "linux")]
    pub fn pause(&mut self) -> std::result::Result<(), String> {
        if self.paused {
            return Ok(());
        }
        self.vcpus_round_trip(
            (VcpuEvent::Pause, VcpuResponse::Paused),
            (VcpuEvent::Resume, VcpuResponse::Resumed),
        )?;
        self.paused = true;
        Ok(())
    }

    /// Wake every vCPU frozen by [`Vmm::pause`]. Idempotent: resuming a running VM is a
    /// no-op. On failure the VM stays paused.
    #[cfg(target_os = "linux")]
    pub fn resume(&mut self) -> std::result::Result<(), String> {
        if !self.paused {
            return Ok(());
        }
        self.vcpus_round_trip(
            (VcpuEvent::Resume, VcpuResponse::Resumed),
            (VcpuEvent::Pause, VcpuResponse::Paused),
        )?;
        self.paused = false;
        Ok(())
    }

    /// The state of the paused VM's vCPUs and of its in-kernel devices (irqchip, PIT, clock),
    /// for [`Vmm::restore_cpu_state`].
    #[cfg(all(target_os = "linux", target_arch = "x86_64"))]
    pub fn save_cpu_state(&mut self) -> std::result::Result<CpuState, String> {
        if !self.paused {
            return Err("the VM is not paused".into());
        }
        let all: Vec<usize> = (0..self.vcpus_handles.len()).collect();
        let (states, res) = self.exchange_vcpus(
            &all,
            "SaveState",
            |_| VcpuEvent::SaveState,
            |got| match got {
                VcpuResponse::State(state) => Ok(*state),
                other => Err(other),
            },
        );
        res?;
        let vcpus = states.into_iter().map(|(_, state)| state).collect();
        let vm = self
            .vm
            .save_state()
            .map_err(|e| format!("saving the VM: {e}"))?;
        Ok(CpuState { vm, vcpus })
    }

    /// Put back into the paused VM the state [`Vmm::save_cpu_state`] took, on vCPUs
    /// configured as the saved ones were.
    #[cfg(all(target_os = "linux", target_arch = "x86_64"))]
    pub fn restore_cpu_state(&mut self, state: CpuState) -> std::result::Result<(), String> {
        if !self.paused {
            return Err("the VM is not paused".into());
        }
        if state.vcpus.len() != self.vcpus_handles.len() {
            return Err(format!(
                "the state has {} vcpus, the VM {}",
                state.vcpus.len(),
                self.vcpus_handles.len()
            ));
        }
        // The VM's clock and interrupt controllers first, as the vCPUs' timers read them.
        self.vm
            .restore_state(&state.vm)
            .map_err(|e| format!("restoring the VM: {e}"))?;
        let vcpus: Vec<Arc<vstate::VcpuState>> = state.vcpus.into_iter().map(Arc::new).collect();
        let all: Vec<usize> = (0..vcpus.len()).collect();
        self.exchange_vcpus(
            &all,
            "RestoreState",
            |i| VcpuEvent::RestoreState(vcpus[i].clone()),
            |got| match got {
                VcpuResponse::Restored => Ok(()),
                other => Err(other),
            },
        )
        .1
    }

    /// Pause the VM and write its snapshot to `dir` ([`snapshot`]): its CPU state, its legacy
    /// and virtio-pci devices' and its RAM. The VM stays paused; its disks are the snapshot's
    /// once it ends. Refused for a VM with devices a snapshot cannot quiesce or keep.
    #[cfg(all(target_os = "linux", target_arch = "x86_64", feature = "snapshot"))]
    pub fn snapshot(&mut self, dir: &std::path::Path) -> std::result::Result<(), String> {
        use std::os::unix::fs::DirBuilderExt;

        self.check_snapshot_devices()?;
        self.pause()?;
        // The devices' threads finish what they are writing to guest memory (a disk batch, a
        // received frame) and write nothing more until the snapshot is taken.
        let _quiet = devices::virtio::quiesce_devices(Duration::from_secs(10))
            .ok_or("the devices did not finish writing guest memory within 10 s")?;
        std::fs::DirBuilder::new()
            .recursive(true)
            .mode(0o700)
            .create(dir)
            .map_err(|e| format!("creating {}: {e}", dir.display()))?;
        let cpu = self.save_cpu_state()?;
        let legacy = self
            .legacy_devices
            .as_ref()
            .ok_or("the VM has no legacy devices to snapshot")?
            .save()
            .map_err(|e| format!("saving the devices: {e}"))?;
        let pci = self
            .pci_device_manager
            .as_ref()
            .map(|pci| {
                pci.transports()
                    .iter()
                    .map(|t| t.lock().unwrap().save_state())
                    .collect()
            })
            .unwrap_or_default();
        let memory =
            snapshot::ram_regions(&self.guest_memory, self.arch_memory_info.shm_start_addr);
        let mut saved =
            snapshot::new_snapshot(cpu, legacy, pci, memory, self.vm_generation_id.is_some());
        snapshot::write(dir, &self.guest_memory, &mut saved)
            .map_err(|e| format!("writing the snapshot: {e}"))
    }

    /// Refuse a VM with a device a snapshot would not keep (virtio-mmio) or whose threads it
    /// cannot keep off guest memory ([`devices::virtio::QUIESCED_DEVICE_TYPES`]).
    #[cfg(all(target_os = "linux", target_arch = "x86_64", feature = "snapshot"))]
    fn check_snapshot_devices(&self) -> std::result::Result<(), String> {
        if !self.mmio_device_manager.virtio_mmio_devices().is_empty() {
            return Err("a snapshot does not keep virtio-mmio devices".into());
        }
        for transport in self
            .pci_device_manager
            .as_ref()
            .map_or(&[][..], |pci| pci.transports())
        {
            let device_type = transport
                .lock()
                .unwrap()
                .device()
                .lock()
                .unwrap()
                .device_type();
            if !devices::virtio::QUIESCED_DEVICE_TYPES.contains(&device_type) {
                return Err(format!(
                    "a snapshot cannot quiesce virtio device type {device_type}"
                ));
            }
        }
        Ok(())
    }

    /// Bring this VM, built on the configuration of the snapshot in `dir` and its vCPUs
    /// started paused, to that snapshot, then run it: memory first (the devices read their
    /// queues' positions from it), then the legacy and virtio-pci devices, then the vCPUs and
    /// the in-kernel devices, and only then wake the virtio devices and the guest. A guest
    /// with a VM generation ID gets this VM's, and the notification that it changed.
    #[cfg(all(target_os = "linux", target_arch = "x86_64", feature = "snapshot"))]
    pub fn restore(&mut self, dir: &std::path::Path) -> std::result::Result<(), String> {
        use vm_memory::{Bytes, GuestAddress};

        let saved = snapshot::read_state(dir).map_err(|e| format!("reading the snapshot: {e}"))?;
        match (saved.vm_generation_id, self.vm_generation_id) {
            (true, None) => {
                return Err(
                    "the snapshot's guest has a VM generation ID: restoring it needs a new one"
                        .into(),
                );
            }
            (false, Some(_)) => {
                return Err("the snapshot's guest has no VM generation ID to change".into());
            }
            _ => {}
        }
        let memory =
            snapshot::ram_regions(&self.guest_memory, self.arch_memory_info.shm_start_addr);
        if memory != saved.memory {
            return Err("the snapshot's memory layout is not this VM's".into());
        }
        let image = snapshot::memory_image(dir, &saved).map_err(|e| e.to_string())?;
        snapshot::load_memory(&self.guest_memory, &memory, &image)
            .map_err(|e| format!("loading the memory image: {e}"))?;
        // The restored RAM holds the snapshot's ID.
        if let Some(id) = &self.vm_generation_id {
            self.guest_memory
                .write_slice(id, GuestAddress(arch::x86_64::layout::VMGENID_ADDR))
                .map_err(|e| format!("writing the VM generation ID: {e}"))?;
        }
        let legacy = self
            .legacy_devices
            .clone()
            .ok_or("the VM has no legacy devices to restore")?;
        legacy
            .restore(&saved.legacy)
            .map_err(|e| format!("restoring the devices: {e}"))?;
        let transports = self
            .pci_device_manager
            .as_ref()
            .map(|pci| pci.transports().to_vec())
            .unwrap_or_default();
        snapshot::restore_transports(&transports, &saved.pci)
            .map_err(|e| format!("restoring the devices: {e}"))?;
        self.restore_cpu_state(saved.cpu)?;
        for transport in &transports {
            transport.lock().unwrap().kick_restored();
        }
        self.resume()?;
        // As QEMU's vmgenid: the guest re-reads the ID on the GPE's Notify.
        if self.vm_generation_id.is_some() {
            legacy
                .acpi_pm
                .lock()
                .unwrap()
                .raise_gpe(arch::x86_64::layout::VMGENID_GPE);
        }
        Ok(())
    }

    /// Ask every vCPU `request` and wait for each to answer. If one does not, `undo` is asked
    /// of those that did, which leaves the VM as it was.
    #[cfg(target_os = "linux")]
    fn vcpus_round_trip(
        &mut self,
        request: (VcpuEvent, VcpuResponse),
        undo: (VcpuEvent, VcpuResponse),
    ) -> std::result::Result<(), String> {
        let all: Vec<usize> = (0..self.vcpus_handles.len()).collect();
        let (answered, res) = self.ask_vcpus(&all, request);
        let Err(e) = res else {
            return Ok(());
        };
        match self.ask_vcpus(&answered, undo).1 {
            Ok(()) => Err(e),
            Err(undo_err) => Err(format!("{e}; undoing it: {undo_err}")),
        }
    }

    /// Send `event` to the vCPUs `ids` and wait for each to answer `want`: the ids of those
    /// that did, and the first failure ([`Vmm::exchange_vcpus`]).
    #[cfg(target_os = "linux")]
    fn ask_vcpus(
        &mut self,
        ids: &[usize],
        (event, want): (VcpuEvent, VcpuResponse),
    ) -> (Vec<usize>, std::result::Result<(), String>) {
        let what = format!("{event:?}");
        let (answered, res) = self.exchange_vcpus(
            ids,
            &what,
            |_| event.clone(),
            |got| {
                if std::mem::discriminant(&got) == std::mem::discriminant(&want) {
                    Ok(())
                } else {
                    Err(got)
                }
            },
        );
        (answered.into_iter().map(|(i, ())| i).collect(), res)
    }

    /// Send each of the vCPUs `ids` the event `event(id)` and wait up to 5 s for its answer,
    /// which `take` accepts or hands back ([`exchange`]).
    #[cfg(target_os = "linux")]
    fn exchange_vcpus<T>(
        &mut self,
        ids: &[usize],
        what: &str,
        event: impl Fn(usize) -> VcpuEvent,
        take: impl FnMut(VcpuResponse) -> std::result::Result<T, VcpuResponse>,
    ) -> (Vec<(usize, T)>, std::result::Result<(), String>) {
        exchange(
            &self.vcpus_handles,
            &mut self.vcpu_exit_code,
            ids,
            what,
            event,
            take,
        )
    }

    /// Configures the system for boot.
    #[allow(clippy::too_many_arguments)]
    pub fn configure_system(
        &self,
        vcpus: &[Vcpu],
        _intc: &IrqChip,
        initrd: &Option<InitrdConfig>,
        _smbios_oem_strings: &Option<Vec<String>>,
        _acpi_enabled: bool,
        _virtio_mmio_devices: &[(u64, u32)],
        _pvh: bool,
        _vm_generation_id: Option<&[u8; 16]>,
        _windows_platform: bool,
        _system_uuid: Option<&[u8; 16]>,
        _tpm: bool,
    ) -> Result<()> {
        #[cfg(target_arch = "x86_64")]
        {
            let cmdline_len = if cfg!(feature = "tee") {
                arch::x86_64::layout::CMDLINE_SEV_SIZE
            } else {
                self.kernel_cmdline.len() + 1
            };

            #[cfg(target_os = "linux")]
            let pci_host_info = self.pci_device_manager.as_ref().map(|pci| {
                pci.acpi_info(arch::x86_64::layout::shm_span_usable(
                    self.arch_memory_info.ram_last_addr,
                ))
            });
            #[cfg(not(target_os = "linux"))]
            let pci_host_info = None;

            arch::x86_64::configure_system(
                &self.guest_memory,
                &self.arch_memory_info,
                vm_memory::GuestAddress(arch::x86_64::layout::CMDLINE_START),
                cmdline_len,
                initrd,
                vcpus.len() as u8,
                _pvh,
                _acpi_enabled,
                _virtio_mmio_devices,
                pci_host_info.as_ref(),
                _vm_generation_id,
                _windows_platform,
                _system_uuid,
                _smbios_oem_strings,
                _tpm,
            )
            .map_err(Error::ConfigureSystem)?;
        }

        #[cfg(target_arch = "aarch64")]
        {
            let vcpu_mpidr = vcpus.iter().map(|cpu| cpu.get_mpidr()).collect();
            fdt::create_fdt(
                &self.guest_memory,
                &self.arch_memory_info,
                vcpu_mpidr,
                self.kernel_cmdline.as_str(),
                self.mmio_device_manager.get_device_info(),
                _intc,
                initrd,
            )
            .map_err(Error::SetupFDT)?;
        }

        #[cfg(target_arch = "aarch64")]
        {
            arch::aarch64::configure_system(
                &self.guest_memory,
                &self.arch_memory_info,
                _smbios_oem_strings,
            )
            .map_err(Error::ConfigureSystem)?;
        }

        #[cfg(target_arch = "riscv64")]
        {
            fdt::create_fdt(
                &self.guest_memory,
                &self.arch_memory_info,
                vcpus.len() as u32,
                self.kernel_cmdline.as_str(),
                self.mmio_device_manager.get_device_info(),
                _intc,
                initrd,
            )
            .map_err(Error::SetupFDT)?;

            arch::riscv64::configure_system(&self.guest_memory, _smbios_oem_strings)
                .map_err(Error::ConfigureSystem)?;
        }

        Ok(())
    }

    /// Returns a reference to the inner `GuestMemoryMmap` object if present, or `None` otherwise.
    pub fn guest_memory(&self) -> &GuestMemoryMmap {
        &self.guest_memory
    }

    /// Waits for all vCPUs to exit and terminates the Firecracker process.
    pub fn stop(&mut self, exit_code: i32) {
        info!("Vmm is stopping.");

        for observer in &self.exit_observers {
            observer
                .lock()
                .expect("Poisoned mutex for exit observer")
                .on_vmm_exit();
        }

        // Exit from Firecracker using the provided exit code. Safe because we're terminating
        // the process anyway.
        unsafe {
            libc::_exit(exit_code);
        }
    }

    /// Returns a reference to the inner KVM Vm object.
    #[cfg(feature = "tee")]
    pub fn kvm_vm(&self) -> &Vm {
        &self.vm
    }

    #[cfg(target_os = "macos")]
    pub fn add_mapping(
        &self,
        reply_sender: Sender<bool>,
        host_addr: u64,
        guest_addr: u64,
        len: u64,
    ) {
        self.vm
            .add_mapping(reply_sender, host_addr, guest_addr, len);
    }

    #[cfg(target_os = "macos")]
    pub fn remove_mapping(&self, reply_sender: Sender<bool>, guest_addr: u64, len: u64) {
        self.vm.remove_mapping(reply_sender, guest_addr, len);
    }
}

/// Send a [`VmCtl`] request's outcome back to its caller, and return it.
#[cfg(any(target_os = "macos", target_os = "linux"))]
fn answer(
    reply: &Sender<std::result::Result<(), String>>,
    res: std::result::Result<(), String>,
) -> std::result::Result<(), String> {
    let _ = reply.send(res.clone());
    res
}

/// Send each of the vCPUs `ids` of `handles` the event `event(id)` and wait up to 5 s for its
/// answer, which `take` accepts or hands back: the accepted answers by vCPU id, and the first
/// failure. A vCPU that exits instead leaves its code in `exit_code` for the `exit_evt`
/// handler.
#[cfg(target_os = "linux")]
fn exchange<T>(
    handles: &[VcpuHandle],
    exit_code: &mut Option<u8>,
    ids: &[usize],
    what: &str,
    event: impl Fn(usize) -> VcpuEvent,
    mut take: impl FnMut(VcpuResponse) -> std::result::Result<T, VcpuResponse>,
) -> (Vec<(usize, T)>, std::result::Result<(), String>) {
    // Answers an earlier, timed-out request left behind would read as this one's.
    for h in handles {
        while let Ok(stale) = h.response_receiver().try_recv() {
            if let VcpuResponse::Exited(code) = stale {
                *exit_code = Some(code);
            }
        }
    }
    let mut failure = None;
    let mut sent = Vec::new();
    for &i in ids {
        match handles[i].send_event(event(i)) {
            Ok(()) => sent.push(i),
            Err(e) => {
                failure = Some(format!("vcpu {i} {what} event: {e:?}"));
                break;
            }
        }
    }
    let deadline = std::time::Instant::now() + Duration::from_secs(5);
    let mut answered = Vec::new();
    for i in sent {
        let got = match handles[i].response_receiver().recv_deadline(deadline) {
            Ok(got) => take(got),
            Err(e) => {
                failure.get_or_insert(format!("vcpu {i} response to {what}: {e}"));
                continue;
            }
        };
        let err = match got {
            Ok(v) => {
                answered.push((i, v));
                continue;
            }
            Err(VcpuResponse::Exited(code)) => {
                *exit_code = Some(code);
                format!("vcpu {i} exited")
            }
            Err(VcpuResponse::Error(e)) => format!("vcpu {i} {what}: {e}"),
            Err(other) => format!("unexpected vcpu {i} response: {other:?}"),
        };
        failure.get_or_insert(err);
    }
    (answered, failure.map_or(Ok(()), Err))
}

impl Subscriber for Vmm {
    /// Handle a read event (EPOLLIN).
    fn process(&mut self, event: &EpollEvent, _: &mut EventManager) {
        let source = event.fd();
        let event_set = event.event_set();

        #[cfg(any(target_os = "macos", target_os = "linux"))]
        if source == self.vm_ctl_rx.as_raw_fd() && event_set == EventSet::IN {
            while let Ok(Some(req)) = self.vm_ctl_rx.try_recv() {
                let res = match req {
                    VmCtl::Pause(ref reply) => answer(reply, self.pause()),
                    VmCtl::Resume(ref reply) => answer(reply, self.resume()),
                    #[cfg(all(target_os = "linux", target_arch = "x86_64", feature = "snapshot"))]
                    VmCtl::Snapshot(ref dir, ref reply) => answer(reply, self.snapshot(dir)),
                    #[cfg(all(target_os = "linux", target_arch = "x86_64", feature = "snapshot"))]
                    VmCtl::Quit => {
                        self.stop(FC_EXIT_CODE_OK as i32);
                        Ok(())
                    }
                };
                if let Err(e) = res {
                    error!("vm {req:?} failed: {e}");
                }
            }
            return;
        }

        if source == self.exit_evt.as_raw_fd() && event_set == EventSet::IN {
            let _ = self.exit_evt.read();
            // Query each vcpu for the exit_code.
            // If the exit_code can't be found on any vcpu, the exit signal came from a
            // device (the i8042 controller or `AcpiPm`), in which case we exit with
            // FC_EXIT_CODE_OK.
            //
            // A guest reset outranks everything (below); otherwise the exit code set up
            // by the guest takes preference over the one reported by a vcpu or a device.
            let vcpu_exit_code = self
                .vcpu_exit_code
                .or_else(|| {
                    self.vcpus_handles.iter().find_map(|handle| {
                        match handle.response_receiver().try_recv() {
                            Ok(VcpuResponse::Exited(exit_code)) => Some(exit_code),
                            _ => None,
                        }
                    })
                })
                .unwrap_or(FC_EXIT_CODE_OK);
            let vmm_exit_code = self.exit_code.load(Ordering::SeqCst);
            // A reset takes precedence over every other code, whether a device (reset_flag)
            // or a vcpu (triple fault, KVM_SYSTEM_EVENT_RESET) signalled it: the supervisor
            // must see it to reboot.
            let exit_code = if self.reset_flag.load(Ordering::SeqCst)
                || vcpu_exit_code == KRUN_EXIT_GUEST_RESET
            {
                debug!("using guest-reset exit code");
                KRUN_EXIT_GUEST_RESET as i32
            } else if vmm_exit_code != i32::MAX {
                debug!("using vmm exit code: {vmm_exit_code}");
                vmm_exit_code
            } else {
                debug!("using vcpu exit code: {vcpu_exit_code}");
                vcpu_exit_code as i32
            };
            self.stop(exit_code);
        } else {
            error!("Spurious EventManager event for handler: Vmm");
        }
    }

    fn interest_list(&self) -> Vec<EpollEvent> {
        // `vm_ctl_rx` is pushed only on macOS and Linux, so `mut` is unused elsewhere.
        #[allow(unused_mut)]
        let mut list = vec![EpollEvent::new(
            EventSet::IN,
            self.exit_evt.as_raw_fd() as u64,
        )];
        #[cfg(any(target_os = "macos", target_os = "linux"))]
        list.push(EpollEvent::new(
            EventSet::IN,
            self.vm_ctl_rx.as_raw_fd() as u64,
        ));
        list
    }
}

#[cfg(all(test, target_os = "linux"))]
mod tests {
    use super::*;

    /// A vCPU thread that answers every event with `answer`.
    fn fake_vcpu(answer: fn() -> VcpuResponse) -> VcpuHandle {
        let (event_tx, event_rx) = crossbeam_channel::unbounded::<VcpuEvent>();
        let (response_tx, response_rx) = crossbeam_channel::unbounded();
        let thread = std::thread::spawn(move || {
            while event_rx.recv().is_ok() {
                response_tx.send(answer()).unwrap();
            }
        });
        VcpuHandle::new(event_tx, response_rx, thread)
    }

    #[test]
    fn exchange_reports_a_vcpus_error_and_keeps_the_others_answers() {
        Vcpu::register_kick_signal_handler();
        let handles = [
            fake_vcpu(|| VcpuResponse::Restored),
            fake_vcpu(|| VcpuResponse::Error("the vcpu is running".into())),
            fake_vcpu(|| VcpuResponse::Exited(3)),
        ];
        let mut exit_code = None;
        let (answered, res) = exchange(
            &handles,
            &mut exit_code,
            &[0, 1, 2],
            "SaveState",
            |_| VcpuEvent::Pause,
            |got| match got {
                VcpuResponse::Restored => Ok(()),
                other => Err(other),
            },
        );
        assert_eq!(answered, [(0, ())]);
        assert_eq!(res, Err("vcpu 1 SaveState: the vcpu is running".into()));
        // The exit is recorded for the exit handler even though an earlier failure is reported.
        assert_eq!(exit_code, Some(3));
    }
}
